      <div className="bg-white rounded-xl border border-slate-200 shadow-sm divide-y divide-slate-100 mt-3">
        {items.map((item, i) => {
          const key = `${groupKey}-${i}`;
          const isChecked = !!checkedItems[key];
          return (
            <label key={i} className="flex items-center gap-4 p-4 cursor-pointer hover:bg-slate-50 transition-colors">
              <input type="checkbox" checked={isChecked} onChange={() => toggleCheck(groupKey, i)} className="accent-indigo-600 w-4 h-4 rounded" />
              <span className={`text-sm ${isChecked ? "text-slate-400 line-through" : "text-slate-700"}`}>{item}</span>
            </label>
          );
        })}
      </div>
    </div>
  );
}

function ChangelogEntry({ version, date, items, pending }) {
  return (
    <div className="relative">
      <div className={`absolute -left-[31px] top-1.5 w-3 h-3 rounded-full border-2 ${pending ? "border-slate-300 bg-white" : "border-indigo-500 bg-white"}`} />
      <div className="flex items-baseline gap-4 mb-3">
        <div className={`serif text-2xl ${pending ? "text-slate-400" : "text-slate-900"}`}>v{version}</div>
        <div className="text-xs tracking-[0.2em] text-slate-400">{date}</div>
      </div>
      <ul className="space-y-1.5 text-sm text-slate-600">
        {items.map((item, i) => (
          <li key={i} className="flex gap-3"><span className="text-indigo-400">\u00b7</span><span>{item}</span></li>
        ))}
      </ul>
    </div>
  );
}

function TechStackCard({ name, version, role }) {
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-4 hover:shadow-md transition-shadow">
      <div className="text-sm font-semibold text-slate-900">{name}</div>
      <div className="text-xs mono text-indigo-500 font-medium mb-1">{version}</div>
      <div className="text-xs text-slate-400">{role}</div>
    </div>
  );
}

function ProgressBar({ percent }) {
  return (
    <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
      <div className={`h-full rounded-full transition-all duration-500 ${percent === 100 ? "bg-emerald-500" : "bg-indigo-500"}`} style={{ width: `${percent}%` }} />
    </div>
  );
}

function CodeBlock({ code, title }) {
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      {title && <div className="px-4 py-2.5 border-b border-slate-100 text-xs text-slate-400 font-medium tracking-wide">{title}</div>}
      <pre className="p-4 mono text-xs text-slate-600 leading-relaxed overflow-x-auto bg-slate-50">{code}</pre>
    </div>
  );
}

function WarningBox({ title, children }) {
  return (
    <div className="bg-rose-50 border border-rose-200 rounded-xl p-5 mt-6">
      <div className="flex gap-3 items-start">
        <AlertTriangle className="text-rose-500 shrink-0 mt-0.5" size={18} />
        <div>
          <div className="text-rose-800 text-sm font-semibold mb-2">{title}</div>
          {children}
        </div>
      </div>
    </div>
  );
}

function GateCard({ name, agent, color, checks }) {
  const colorMap = { indigo: "border-indigo-200 bg-indigo-50 text-indigo-700", rose: "border-rose-200 bg-rose-50 text-rose-700", violet: "border-violet-200 bg-violet-50 text-violet-700", emerald: "border-emerald-200 bg-emerald-50 text-emerald-700" };
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 hover:shadow-md transition-shadow">
      <div className="flex items-center justify-between mb-4">
        <div className="text-lg font-semibold text-slate-900">{name}</div>
        <span className={`text-xs px-2.5 py-1 rounded-full border font-medium ${colorMap[color]}`}>{agent}</span>
      </div>
      <div className="space-y-2">
        {checks.map((check, i) => (
          <div key={i} className="flex items-start gap-2.5 text-sm text-slate-600">
            <CheckCircle size={16} className={`shrink-0 mt-0.5 ${colorMap[color].split(" ")[2]}`} />
            <span>{check}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

