import { useState, useEffect, useRef, useMemo } from "react";
import {
  GitBranch, Train, Database, ShieldCheck, AlertTriangle, ArrowRight,
  Check, Layers, Terminal, Lock, GitPullRequest, Circle, CreditCard,
  Activity, CheckCircle, FileText, Zap, Shield, XCircle, Server,
  ClipboardCheck, Search, ChevronDown, ChevronRight, X, BookOpen,
} from "lucide-react";

/* ========== DATA CONSTANTS ========== */

const TECH_STACK = [
  { name: "Next.js", version: "16.2.3", role: "App Router only" },
