  { name: "TypeScript", version: "5.6+ strict", role: "Zero any types" },
  { name: "Tailwind CSS", version: "4.x", role: "Styling" },
  { name: "shadcn/ui", version: "latest", role: "Component library" },
  { name: "Supabase", version: "managed", role: "Auth + DB + Storage" },
  { name: "Dodo Payments", version: "\u2014", role: "Billing (never Stripe)" },
  { name: "Resend", version: "\u2014", role: "Transactional email" },
  { name: "PostHog", version: "\u2014", role: "Analytics + errors (day 1)" },
  { name: "Sentry", version: "\u2014", role: "Error tracking (add when paying users)" },
  { name: "pnpm", version: "9.x", role: "Package manager" },
  { name: "Node.js", version: "20 LTS", role: "Runtime" },
];

const HARD_RULES = [
  "App Router only \u2014 no Pages Router",
  "Supabase for all data \u2014 no other ORM",
  "RLS on every table \u2014 Sage blocks deploy without it",
  "Railway for all hosting \u2014 no Vercel",
  "Dodo Payments for billing \u2014 no Stripe",
  "pnpm only \u2014 no npm/yarn",
  "Node 20 LTS \u2014 no other runtime",
  "TypeScript strict \u2014 zero any types",
  "Health check at /api/health \u2014 required",
  "Pino for logs \u2014 never console.log in prod",
  "Rate limit every public API \u2014 Upstash Redis",
  "Feature deps deferred to build phase",
  "Workers as separate Railway services",
  "Private networking for internal services",
  "Standalone Next.js output for Railway",
];

const FORBIDDEN_ITEMS = [
  "Vercel", "Stripe", "Prisma / Drizzle", "NextAuth.js",
  "Pages Router", "@supabase/auth-helpers-nextjs",
  "npm / yarn", "CSS modules / styled-components",
  "Self-hosted Postgres", "any types", "console.log in prod",
  "AWS Lambda / Cloudflare Workers",
];

const DEPLOY_STEPS = [
  "Branch off Develop \u2192 feature/your-thing",
  "Open PR into Develop \u2192 squash & merge",
  "Railway Develop auto-deploys \u2192 smoke test",
  "Open PR from Develop \u2192 Staging",
  "Railway Staging auto-deploys \u2192 full QA + migration check",
  "Open PR from Staging \u2192 Main",
  "Railway Main auto-deploys \u2192 production live",
];

const SECURITY_CHECKLIST = [
  "Passwords hashed with bcrypt 12+ or Argon2",
  "No secrets in client code or git",
  "CSRF protection on state-changing operations",
  "Rate limiting on auth endpoints",
  "Account lockout after 10 failed attempts",
  "Secure password reset (time-limited, single-use tokens)",
  "Session invalidation on password change",
  "Email verification before full access",
  "2FA support for enterprise (TOTP)",
  "Audit log for sensitive operations",
];

const NON_NEGOTIABLES = [
  "Never work directly on Main.",
  "Never test unfinished work on Main.",
  "Never connect non-prod envs to Boldteq - Main.",
  "Never make DB changes in production first.",
  "Never use the service role key in the frontend.",
  "Never treat Railway replicas as environments.",
  "Every environment owns its variables \u2014 no sharing.",
  "Every feature travels: feature \u2192 Develop \u2192 Staging \u2192 Main.",
  "Auth, billing, error boundaries ship in v1 \u2014 not later.",
  "TypeScript strict mode. Zero any types.",
  "Every API route has Zod input validation.",
  "Every mutation has error handling.",
  "Mobile-first, fully responsive from day 1.",
  "No hardcoded secrets. Environment variables only.",
];

const QUALITY_GATES = [
  { name: "Koda's 5-Gate", agent: "Koda (Builder)", color: "indigo", checks: [
    "TypeScript strict \u2014 pnpm tsc --noEmit",
    "ESLint clean \u2014 pnpm eslint . --max-warnings=0",
    "Vitest + coverage \u2265 70% on touched files",
    "Playwright E2E \u2014 happy path passes",
    "Lighthouse \u2265 0.90 on affected routes",
  ]},
  { name: "Sage Security Gate", agent: "Sage (Code Reviewer)", color: "rose", checks: [
    "Secret scan \u2014 no keys in code",
    "Dependency audit \u2014 no critical CVEs",
    "RLS audit \u2014 every table has policies",
    "Accessibility \u2014 axe-core WCAG AA",
    "OWASP headers check",
    "GDPR deletion endpoint exists",
  ]},
  { name: "Luna Test Gate", agent: "Luna (Tester)", color: "violet", checks: [
    "Every touched file has corresponding test file",
    "Exceptions: pages, layouts, error/loading boundaries, shadcn primitives, config files",
  ]},
  { name: "Bolt Deploy Gate", agent: "Bolt (Deployment)", color: "emerald", checks: [
    "Koda + Sage gates passed",
    "All env vars present in Railway",
    "Migrations applied to target Supabase",
    "Build succeeds (standalone output)",
    "Health check returns 200",
  ]},
];

const MONITORING_TOOLS = [
  { name: "PostHog", role: "Analytics + error tracking (day 1)", what: "Feature flags, session replay, funnel analysis, activation events, basic error tracking. Free up to 1M events/month.", color: "indigo" },
  { name: "Sentry", role: "Advanced error tracking (add when paying users)", what: "Source maps, stack traces, release tracking, real-time alerts. Add once product has paying users and fast debugging matters.", color: "rose" },
  { name: "Pino", role: "Structured logging", what: "JSON logs in prod. Never console.log. Searchable, parseable, alertable.", color: "amber" },
  { name: "/api/health", role: "Health check", what: "Returns 200 + timestamp. Railway uses this for deploy readiness and auto-restart.", color: "emerald" },
];

const PERF_TARGETS = [
  { metric: "LCP", target: "< 2.5s" },
  { metric: "CLS", target: "< 0.1" },
  { metric: "INP", target: "< 200ms" },
  { metric: "TTFB", target: "< 600ms" },
];

const SETUP_CHECKLISTS = [
  { title: "GitHub", groupKey: "github", items: [
    "Set Main as default branch",
    "Create Develop and Staging branches off Main",
    "Enable branch protection on Main (1 approval, no force push, no delete)",
    "Enable branch protection on Staging (1 approval, PR required)",
    "Enable PR-required on Develop",
    "Configure squash-merge for feature PRs",
  ]},
  { title: "Railway", groupKey: "railway", items: [
    "Create project with 3 environments: Main, Staging, Develop",
    "Bind each env to its matching GitHub branch",
    "Set per-environment variables (no copy-paste from prod)",
    "Set Develop & Staging to 1 replica",
    "Set Main to 1 replica baseline, scale on metrics only",
    "Verify deploy webhook fires on correct branch",
    "Add worker services (jobs + cron) + Redis",
    "Enable private networking between services",
  ]},
  { title: "Supabase", groupKey: "supabase", items: [
    "Create 3 projects: Boldteq - Develop, Staging, Main",
    "Move all schema to /supabase/migrations in the repo",
    "Stop making dashboard edits in Main",
    "Add anon + service keys to matching Railway env only",
    "Document RLS policies in the repo",
    "Set up daily backup on Boldteq - Main",
  ]},
  { title: "Auth", groupKey: "auth-setup", items: [
    "Install @supabase/ssr (NOT auth-helpers-nextjs)",
    "Configure Supabase Auth providers (email, OAuth)",
    "Write RLS policies for all tables",
    "Set up rate limiting on auth endpoints (Upstash)",
    "Add email verification flow",
  ]},
  { title: "Billing", groupKey: "billing-setup", items: [
    "Create Dodo Payments account + products",
    "Set up webhook endpoint /api/webhooks/dodo",
    "Add plan tier column to users table",
    "Configure RLS policies gated by plan tier",
  ]},
  { title: "Monitoring", groupKey: "monitoring-setup", items: [
    "Set up PostHog project + install SDK (day 1)",
    "Set up Sentry project + install SDK (when paying users)",
    "Configure Pino logger (replace all console.log)",
    "Add /api/health endpoint",
    "Set Railway health check to /api/health",
  ]},
];

const CHANGELOG_ENTRIES = [
  { version: "3.0.0", date: "2026.04.12", items: [
    "Docs dashboard: search, page navigation, collapsible sidebar",
    "Cmd+K search across all rules, checklist items, tech stack",
    "Hash-based navigation for direct linking",
  ]},
  { version: "2.0.0", date: "2026.04.12", items: [
    "Full redesign: light theme, comprehensive content",
    "Added Stack A spec, Auth, Billing, Monitoring, Quality Gates sections",
    "Expanded checklist from 3 to 6 groups with progress tracking",
  ]},
  { version: "1.0.0", date: "2026.04.12", items: [
    "Initial operating manual created",
    "Mapping locked: Develop / Staging / Main across all three layers",
    "Eight rules ratified",
  ]},
];

const SIDEBAR_GROUPS = [
  { name: "Getting Started", icon: BookOpen, sections: [
    { id: "overview", label: "Overview", icon: Layers },
    { id: "stack", label: "Stack A", icon: Terminal },
  ]},
  { name: "Infrastructure", icon: Server, sections: [
    { id: "mapping", label: "Env Mapping", icon: GitBranch },
    { id: "flow", label: "Deploy Flow", icon: ArrowRight },
    { id: "github", label: "GitHub", icon: GitPullRequest },
    { id: "railway", label: "Railway", icon: Train },
    { id: "supabase", label: "Supabase", icon: Database },
  ]},
  { name: "Security & Payments", icon: Shield, sections: [
    { id: "auth", label: "Auth & Security", icon: ShieldCheck },
    { id: "billing", label: "Billing", icon: CreditCard },
  ]},
  { name: "Operations", icon: Activity, sections: [
    { id: "monitoring", label: "Monitoring", icon: Activity },
    { id: "gates", label: "Quality Gates", icon: CheckCircle },
    { id: "rules", label: "Non-Negotiables", icon: Lock },
  ]},
  { name: "Setup", icon: ClipboardCheck, sections: [
    { id: "checklist", label: "Setup Checklist", icon: ClipboardCheck },
    { id: "changelog", label: "Changelog", icon: FileText },
  ]},
];

/* ========== MAIN COMPONENT ========== */

export default function BoldteqSaasFlowSetup() {
  const [activePage, setActivePage] = useState(() => {
    const hash = window.location.hash.slice(1);
    const allIds = SIDEBAR_GROUPS.flatMap(g => g.sections.map(s => s.id));
    return allIds.includes(hash) ? hash : "overview";
  });
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [collapsedGroups, setCollapsedGroups] = useState({});
  const [checkedItems, setCheckedItems] = useState({});
  const searchInputRef = useRef(null);

  const toggleCheck = (groupKey, index) => {
    setCheckedItems((prev) => {
      const key = `${groupKey}-${index}`;
      return { ...prev, [key]: !prev[key] };
    });
  };

  const getGroupProgress = (groupKey, totalItems) => {
    let checked = 0;
    for (let i = 0; i < totalItems; i++) {
      if (checkedItems[`${groupKey}-${i}`]) checked++;
    }
    return Math.round((checked / totalItems) * 100);
  };

  const toggleGroup = (groupName) => {
    setCollapsedGroups(prev => ({ ...prev, [groupName]: !prev[groupName] }));
  };

  const navigateTo = (pageId) => {
    setActivePage(pageId);
    window.location.hash = pageId;
    window.scrollTo(0, 0);
    // Auto-expand the group containing this page
    SIDEBAR_GROUPS.forEach(g => {
      if (g.sections.some(s => s.id === pageId) && collapsedGroups[g.name]) {
        setCollapsedGroups(prev => ({ ...prev, [g.name]: false }));
      }
    });
  };

  // Cmd+K shortcut
  useEffect(() => {
    const handler = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setSearchOpen(prev => !prev);
        setSearchQuery("");
      }
      if (e.key === "Escape") {
        setSearchOpen(false);
        setSearchQuery("");
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, []);

  // Auto-focus search input
  useEffect(() => {
    if (searchOpen && searchInputRef.current) {
      setTimeout(() => searchInputRef.current?.focus(), 50);
    }
  }, [searchOpen]);

  // Hash change listener
  useEffect(() => {
    const onHash = () => {
      const hash = window.location.hash.slice(1);
      const allIds = SIDEBAR_GROUPS.flatMap(g => g.sections.map(s => s.id));
      if (allIds.includes(hash)) setActivePage(hash);
    };
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  // Search index
  const searchIndex = useMemo(() => {
    const items = [];
    SIDEBAR_GROUPS.forEach(group => {
      group.sections.forEach(s => {
        items.push({ text: s.label, sectionId: s.id, section: s.label, type: "page" });
      });
    });
    TECH_STACK.forEach(t => {
      items.push({ text: `${t.name} ${t.version} \u2014 ${t.role}`, sectionId: "stack", section: "Stack A", type: "tech" });
    });
    HARD_RULES.forEach(r => {
      items.push({ text: r, sectionId: "stack", section: "Stack A", type: "rule" });
    });
    FORBIDDEN_ITEMS.forEach(f => {
      items.push({ text: f, sectionId: "stack", section: "Stack A", type: "forbidden" });
    });
    DEPLOY_STEPS.forEach(s => {
      items.push({ text: s, sectionId: "flow", section: "Deploy Flow", type: "step" });
    });
    SECURITY_CHECKLIST.forEach(s => {
      items.push({ text: s, sectionId: "auth", section: "Auth & Security", type: "security" });
    });
    NON_NEGOTIABLES.forEach(r => {
      items.push({ text: r, sectionId: "rules", section: "Non-Negotiables", type: "rule" });
    });
    QUALITY_GATES.forEach(g => {
      g.checks.forEach(c => {
        items.push({ text: c, sectionId: "gates", section: "Quality Gates", type: "gate" });
      });
    });
    MONITORING_TOOLS.forEach(t => {
      items.push({ text: `${t.name} \u2014 ${t.what}`, sectionId: "monitoring", section: "Monitoring", type: "tool" });
    });
    SETUP_CHECKLISTS.forEach(g => {
      g.items.forEach(item => {
        items.push({ text: item, sectionId: "checklist", section: "Setup Checklist", type: "checklist" });
      });
    });
    return items;
  }, []);

  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return {};
    const q = searchQuery.toLowerCase();
    const matches = searchIndex.filter(item => item.text.toLowerCase().includes(q));
    const grouped = {};
    matches.forEach(m => {
      if (!grouped[m.section]) grouped[m.section] = [];
      grouped[m.section].push(m);
    });
    return grouped;
  }, [searchQuery, searchIndex]);

  const hasResults = Object.keys(searchResults).length > 0;

  // Find current breadcrumb
  const currentGroup = SIDEBAR_GROUPS.find(g => g.sections.some(s => s.id === activePage));
  const currentSection = currentGroup?.sections.find(s => s.id === activePage);

  return (
    <div className="min-h-screen bg-slate-50">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@300;400;500;600&display=swap');
        .serif { font-family: 'Instrument Serif', serif; font-weight: 400; }
        .mono { font-family: 'JetBrains Mono', monospace; }
        body { font-family: 'Inter', system-ui, sans-serif; margin: 0; }
        * { scrollbar-width: thin; scrollbar-color: #cbd5e1 transparent; }
      `}</style>

      {/* TOPBAR */}
      <header className="fixed top-0 left-0 right-0 h-14 bg-white/80 backdrop-blur-md border-b border-slate-200 z-30 flex items-center px-6">
        <div className="flex items-center gap-2 w-[236px] shrink-0">
          <div className="w-7 h-7 bg-indigo-600 rounded-lg flex items-center justify-center">
            <BookOpen size={14} className="text-white" />
          </div>
          <span className="text-sm font-semibold text-slate-900">Boldteq Docs</span>
        </div>

        <div className="flex-1 flex justify-center">
          <button
            onClick={() => { setSearchOpen(true); setSearchQuery(""); }}
            className="flex items-center gap-3 bg-slate-100 hover:bg-slate-200 transition-colors rounded-lg px-4 py-2 w-full max-w-md text-left"
          >
            <Search size={16} className="text-slate-400" />
            <span className="text-sm text-slate-400 flex-1">Search documentation...</span>
            <kbd className="hidden sm:inline-flex items-center gap-0.5 text-[10px] text-slate-400 bg-white border border-slate-200 rounded px-1.5 py-0.5 font-mono">
              \u2318K
            </kbd>
          </button>
        </div>

        <div className="w-[236px] shrink-0 flex items-center justify-end gap-3">
          <span className="text-xs bg-slate-100 text-slate-500 px-2.5 py-1 rounded-full font-medium">v3.0.0</span>
          <span className="flex items-center gap-1.5 text-xs text-emerald-600 font-medium">
            <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full" />
            Live
          </span>
        </div>
      </header>

      {/* SIDEBAR */}
      <aside className="fixed top-14 left-0 bottom-0 w-[260px] bg-white border-r border-slate-200 z-20 overflow-y-auto py-4 px-3">
        {SIDEBAR_GROUPS.map((group) => {
          const GroupIcon = group.icon;
          const isCollapsed = !!collapsedGroups[group.name];
          const isActiveGroup = group.sections.some(s => s.id === activePage);
          return (
            <div key={group.name} className="mb-1">
              <button
                onClick={() => toggleGroup(group.name)}
                className={`flex items-center gap-2 w-full text-left text-[11px] tracking-[0.12em] uppercase py-2 px-2 rounded-md transition-colors ${
                  isActiveGroup ? "text-slate-700 font-semibold" : "text-slate-400 font-medium hover:text-slate-600"
                }`}
              >
                {isCollapsed ? <ChevronRight size={12} /> : <ChevronDown size={12} />}
                <GroupIcon size={13} />
                <span>{group.name}</span>
              </button>
              {!isCollapsed && (
                <div className="ml-2 mb-2">
                  {group.sections.map((s) => {
                    const SIcon = s.icon;
                    const isActive = activePage === s.id;
                    return (
                      <button
                        key={s.id}
                        onClick={() => navigateTo(s.id)}
                        className={`flex items-center gap-2.5 w-full text-left text-[13px] py-1.5 px-3 rounded-lg transition-all ${
                          isActive
                            ? "bg-indigo-50 text-indigo-700 font-medium"
                            : "text-slate-500 hover:text-slate-700 hover:bg-slate-50"
                        }`}
                      >
                        <SIcon size={14} className={isActive ? "text-indigo-500" : "text-slate-400"} />
                        <span>{s.label}</span>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}

        <div className="mt-4 mx-1 p-3.5 bg-indigo-50 rounded-xl border border-indigo-100">
          <div className="text-[10px] text-indigo-600 font-semibold tracking-[0.15em] mb-1.5">PRINCIPLE</div>
          <p className="serif italic text-slate-600 text-[13px] leading-snug">
            Production-grade is not complexity. It is predictability.
          </p>
        </div>
      </aside>

      {/* MAIN CONTENT */}
      <main className="ml-[260px] mt-14 min-h-[calc(100vh-56px)]">
        <div className="max-w-4xl mx-auto px-10 py-8">
          {/* Breadcrumb */}
          {currentGroup && currentSection && (
