            <div className="max-h-[50vh] overflow-y-auto">
              {searchQuery.trim() === "" ? (
                <div className="p-3">
                  <div className="text-[10px] tracking-[0.15em] text-slate-400 font-medium uppercase px-2 py-1.5">Quick Navigation</div>
                  {SIDEBAR_GROUPS.flatMap(g => g.sections).map((s) => {
                    const SIcon = s.icon;
                    return (
                      <button
                        key={s.id}
                        onClick={() => { navigateTo(s.id); setSearchOpen(false); setSearchQuery(""); }}
                        className="flex items-center gap-3 w-full text-left px-3 py-2 rounded-lg hover:bg-indigo-50 transition-colors text-sm text-slate-600"
                      >
                        <SIcon size={14} className="text-slate-400" />
                        <span>{s.label}</span>
                      </button>
                    );
                  })}
                </div>
              ) : hasResults ? (
                <div className="p-3">
                  {Object.entries(searchResults).map(([section, items]) => (
                    <div key={section}>
                      <div className="text-[10px] tracking-[0.15em] text-slate-400 font-medium uppercase px-2 py-1.5 mt-2 first:mt-0">{section}</div>
                      {items.slice(0, 5).map((item, i) => (
                        <button
                          key={i}
                          onClick={() => { navigateTo(item.sectionId); setSearchOpen(false); setSearchQuery(""); }}
                          className="flex items-center gap-3 w-full text-left px-3 py-2 rounded-lg hover:bg-indigo-50 transition-colors"
                        >
                          <Search size={12} className="text-slate-300 shrink-0" />
                          <span className="text-sm text-slate-700 truncate">{item.text}</span>
                          <span className="text-[10px] text-slate-400 shrink-0 ml-auto">{item.type}</span>
                        </button>
                      ))}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="p-8 text-center text-sm text-slate-400">No results found for &ldquo;{searchQuery}&rdquo;</div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

