          <div className="flex gap-2"><Check size={16} className="text-emerald-500 shrink-0 mt-0.5" /> Webhook-driven \u2014 integrates with Supabase for status sync</div>
        </div>
      </SubBlock>
      <SubBlock title="Integration pattern">
        <CodeBlock title="Billing flow" code={`1. User selects plan \u2192 call Dodo checkout API
2. Dodo handles payment page (hosted)
3. Webhook fires on success \u2192 /api/webhooks/dodo
4. Webhook handler updates user's plan in Supabase
5. RLS policies gate features by plan tier
6. Billing portal link \u2192 Dodo hosted portal`} />
      </SubBlock>
      <SubBlock title="Pricing structure">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 text-sm text-slate-700 space-y-2">
          <div>Every SaaS ships with <span className="font-semibold">3\u20134 tiers</span></div>
          <div>Free tier \u2192 generous enough to demo, limited enough to convert</div>
          <div>Pro tier \u2192 core target, majority of revenue</div>
          <div>Business/Enterprise \u2192 higher limits, priority support</div>
          <div className="text-slate-400 italic mt-2">Ledger agent models LTV/CAC before launch. Kill gate: LTV/CAC &lt; 3</div>
        </div>
      </SubBlock>
    </div>
  );
}

function MonitoringPage() {
  return (
    <div>
      <SectionHeader number="09" title="Monitoring & Logging" subtitle="See everything. Log everything. Never console.log." />
      <div className="grid md:grid-cols-2 gap-4 mb-8">
        {MONITORING_TOOLS.map((tool, i) => (
          <div key={i} className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
            <div className={`text-xs tracking-[0.2em] text-${tool.color}-600 font-medium mb-2`}>{tool.role.toUpperCase()}</div>
            <div className="text-lg font-semibold text-slate-900 mb-2">{tool.name}</div>
            <p className="text-sm text-slate-600">{tool.what}</p>
          </div>
        ))}
      </div>
      <SubBlock title="Post-deploy monitoring">
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-5">
          <div className="text-sm text-slate-700 space-y-2">
            <div className="font-semibold text-amber-800 mb-1">30-minute post-deploy watch window</div>
            <div>Hawk agent monitors error rate + Railway health for 30 min after every production deploy.</div>
            <div>If error rate exceeds threshold \u2192 <span className="font-semibold text-rose-700">automatic rollback</span>.</div>
          </div>
        </div>
      </SubBlock>
      <SubBlock title="Performance targets">
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="grid grid-cols-2 md:grid-cols-4 divide-x divide-slate-200">
            {PERF_TARGETS.map((m, i) => (
              <div key={i} className="p-4 text-center">
                <div className="text-xs text-slate-400 font-medium mb-1">{m.metric}</div>
                <div className="text-lg font-semibold text-slate-900 mono">{m.target}</div>
              </div>
            ))}
          </div>
        </div>
      </SubBlock>
    </div>
  );
}

function GatesPage() {
  return (
    <div>
      <SectionHeader number="10" title="Quality Gates" subtitle="Every feature passes these gates before shipping." />
      <div className="space-y-4">
        {QUALITY_GATES.map((gate, i) => (
          <GateCard key={i} {...gate} />
        ))}
      </div>
    </div>
  );
}

function RulesPage() {
  return (
    <div>
      <SectionHeader number="11" title="Non-Negotiables" subtitle="Break these and the deploy is blocked." />
      <div className="grid md:grid-cols-2 gap-3">
        {NON_NEGOTIABLES.map((rule, i) => (
          <div key={i} className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 hover:shadow-md transition-shadow">
            <div className="serif text-indigo-400 text-2xl mb-2">{String(i + 1).padStart(2, "0")}</div>
            <p className="text-sm text-slate-700 leading-relaxed">{rule}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

function ChecklistPage({ checkedItems, toggleCheck, getGroupProgress }) {
  return (
    <div>
      <SectionHeader number="12" title="Setup Checklist" subtitle="One-time setup per project. Do these in order." />
      {SETUP_CHECKLISTS.map((group, i) => (
        <ChecklistGroup
          key={i}
          title={group.title}
          groupKey={group.groupKey}
          items={group.items}
          checkedItems={checkedItems}
          toggleCheck={toggleCheck}
          getGroupProgress={getGroupProgress}
        />
      ))}
    </div>
  );
}

function ChangelogPage() {
  return (
    <div>
      <SectionHeader number="13" title="Changelog" subtitle="Update this file every time the system evolves." />
      <div className="border-l-2 border-slate-200 pl-6 space-y-8">
        {CHANGELOG_ENTRIES.map((entry, i) => (
          <ChangelogEntry key={i} {...entry} />
        ))}
        <ChangelogEntry version="next" date="\u2014" items={["Add CI/CD pipeline section once GitHub Actions are live", "Document on-call + incident response"]} pending />
      </div>
    </div>
