}

/* ========== SHARED COMPONENTS ========== */

function SectionHeader({ number, title, subtitle }) {
  return (
    <div className="mb-10 pb-6 border-b border-slate-200">
      <div className="text-xs tracking-[0.3em] text-indigo-500 font-medium mb-3">SECTION {number}</div>
      <h2 className="serif text-5xl text-slate-900 mb-2">{title}</h2>
      <p className="serif italic text-lg text-slate-400">{subtitle}</p>
