}

function LayerCard({ icon, label, title, question, role }) {
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 hover:shadow-md transition-shadow">
      <div className="flex items-center justify-between mb-6">
        <div className="text-indigo-500">{icon}</div>
        <div className="text-xs text-slate-400 tracking-[0.2em] font-medium">{label}</div>
      </div>
      <h3 className="serif text-3xl text-slate-900 mb-3">{title}</h3>
      <p className="serif italic text-slate-500 text-base mb-4 leading-snug">{question}</p>
      <div className="text-xs text-slate-400 tracking-wider pt-4 border-t border-slate-100">{role}</div>
    </div>
  );
}

function MappingRow({ layer, dev, stg, prod, last }) {
  return (
    <div className={`grid grid-cols-4 ${!last ? "border-b border-slate-100" : ""} hover:bg-slate-50 transition-colors`}>
      <div className="p-5 text-xs text-slate-400 tracking-wider flex items-center font-medium">{layer}</div>
      <div className="p-5 text-sm text-emerald-700 font-medium">{dev}</div>
      <div className="p-5 text-sm text-amber-700 font-medium">{stg}</div>
      <div className="p-5 text-sm text-rose-700 font-medium">{prod}</div>
    </div>
  );
}

function PipelineCard({ color, title, items }) {
  const colorMap = { emerald: "bg-emerald-50 border-emerald-200 text-emerald-700", amber: "bg-amber-50 border-amber-200 text-amber-700", rose: "bg-rose-50 border-rose-200 text-rose-700" };
  const dotMap = { emerald: "text-emerald-500", amber: "text-amber-500", rose: "text-rose-500" };
  return (
    <div className={`border rounded-xl ${colorMap[color]} p-5`}>
      <div className="text-xs tracking-[0.2em] mb-4 font-medium">{title.toUpperCase()}</div>
      <div className="space-y-2 text-sm text-slate-700">
        {items.map((item, i) => (
          <div key={i} className="flex gap-2 items-center">
            <Circle size={6} className={dotMap[color]} fill="currentColor" />
            <span>{item}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function FlowStep({ label, sub, color }) {
  const colorMap = { emerald: "border-emerald-300 text-emerald-700 bg-emerald-50", amber: "border-amber-300 text-amber-700 bg-amber-50", rose: "border-rose-300 text-rose-700 bg-rose-50" };
  const cls = color ? colorMap[color] : "border-slate-300 text-slate-700 bg-white";
  return (
    <div className={`border ${cls} px-4 py-3 min-w-[120px] text-center rounded-lg`}>
      <div className="text-sm font-semibold">{label}</div>
      <div className="text-[10px] text-slate-400 tracking-wider mt-1 font-medium">{sub.toUpperCase()}</div>
    </div>
  );
}

function SubBlock({ title, children }) {
  return (
    <div className="mb-10">
      <h3 className="text-xs tracking-[0.3em] text-slate-400 font-medium mb-4">{title.toUpperCase()}</h3>
      {children}
    </div>
  );
}

function BranchRow({ name, desc, color }) {
  const colorMap = { rose: "text-rose-600", amber: "text-amber-600", emerald: "text-emerald-600", slate: "text-slate-500" };
  return (
    <div className="flex items-center gap-4 py-3 px-5">
      <GitBranch size={16} className={colorMap[color]} />
      <div className={`mono text-sm w-32 font-medium ${colorMap[color]}`}>{name}</div>
      <div className="text-sm text-slate-500">{desc}</div>
    </div>
  );
}

function ProtectionTable() {
  const rules = [
    ["Require PR before merge", true, true, true],
    ["Require approvals", "1", "1", "\u2014"],
    ["Require conversation resolution", true, true, false],
    ["Block force push", true, true, false],
    ["Block branch deletion", true, true, false],
  ];
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="grid grid-cols-4 border-b border-slate-200 bg-slate-50 text-xs tracking-[0.2em] font-medium">
        <div className="p-4 text-slate-400">RULE</div>
        <div className="p-4 text-rose-600">MAIN</div>
        <div className="p-4 text-amber-600">STAGING</div>
        <div className="p-4 text-emerald-600">DEVELOP</div>
      </div>
      {rules.map(([rule, m, s, d], i) => (
        <div key={i} className="grid grid-cols-4 border-b border-slate-100 last:border-0 text-sm">
          <div className="p-4 text-slate-600">{rule}</div>
          <Cell value={m} />
          <Cell value={s} />
          <Cell value={d} />
        </div>
      ))}
    </div>
  );
}

function Cell({ value }) {
  if (value === true) return <div className="p-4 text-emerald-500"><Check size={16} /></div>;
  if (value === false) return <div className="p-4 text-slate-300">\u2014</div>;
  return <div className="p-4 text-slate-700 font-medium">{value}</div>;
}

function EnvRow({ env, branch, replicas, color }) {
  const dotMap = { emerald: "bg-emerald-400", amber: "bg-amber-400", rose: "bg-rose-400" };
  const textMap = { emerald: "text-emerald-700", amber: "text-amber-700", rose: "text-rose-700" };
  return (
    <div className="grid grid-cols-3 items-center p-5">
      <div className="flex items-center gap-3">
        <span className={`w-2 h-2 rounded-full ${dotMap[color]}`} />
        <span className={`text-sm font-medium ${textMap[color]}`}>{env}</span>
      </div>
      <div className="text-sm text-slate-500"><span className="text-slate-300">branch \u2192</span> {branch}</div>
      <div className="text-sm text-slate-500"><span className="text-slate-300">replicas \u2192</span> {replicas}</div>
    </div>
  );
}

function EnvVarBlock({ title, color, vars }) {
  const colorMap = { emerald: "border-emerald-200 text-emerald-700 bg-emerald-50", amber: "border-amber-200 text-amber-700 bg-amber-50", rose: "border-rose-200 text-rose-700 bg-rose-50" };
  return (
    <div className={`rounded-xl border overflow-hidden ${colorMap[color].split(" ")[0]} bg-white`}>
      <div className={`px-4 py-3 border-b text-xs tracking-[0.2em] font-medium ${colorMap[color]}`}>{title.toUpperCase()}</div>
      <div className="p-4 space-y-1.5 mono text-xs text-slate-600 bg-white">
        {vars.map((v, i) => <div key={i}>{v}</div>)}
      </div>
    </div>
  );
}

function SupabaseCard({ name, purpose, color }) {
  const colorMap = { emerald: "border-emerald-200 text-emerald-600 bg-emerald-50", amber: "border-amber-200 text-amber-600 bg-amber-50", rose: "border-rose-200 text-rose-600 bg-rose-50" };
  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5 hover:shadow-md transition-shadow">
